namespace RonSijm.FluidHumidifier.Factories.SageMaker;

public class OptimizationJobFactory(string resourceName = null, Action<Humidifier.SageMaker.OptimizationJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.OptimizationJob>(resourceName)
{

    internal List<InnerOptimizationJobOptimizationConfigFactory> OptimizationConfigsFactories { get; set; } = [];

    internal InnerOptimizationJobOptimizationJobOutputConfigFactory OutputConfigFactory { get; set; }

    internal InnerOptimizationJobStoppingConditionFactory StoppingConditionFactory { get; set; }

    internal InnerOptimizationJobOptimizationVpcConfigFactory VpcConfigFactory { get; set; }

    internal InnerOptimizationJobOptimizationJobModelSourceFactory ModelSourceFactory { get; set; }

    protected override Humidifier.SageMaker.OptimizationJob Create()
    {
        var optimizationJobResult = CreateOptimizationJob();
        factoryAction?.Invoke(optimizationJobResult);

        return optimizationJobResult;
    }

    private Humidifier.SageMaker.OptimizationJob CreateOptimizationJob()
    {
        var optimizationJobResult = new Humidifier.SageMaker.OptimizationJob
        {
            GivenName = InputResourceName,
        };

        return optimizationJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.OptimizationJob result)
    {
        base.CreateChildren(result);

        result.OptimizationConfigs = OptimizationConfigsFactories.Any() ? OptimizationConfigsFactories.Select(x => x.Build()).ToList() : null;
        result.OutputConfig ??= OutputConfigFactory?.Build();
        result.StoppingCondition ??= StoppingConditionFactory?.Build();
        result.VpcConfig ??= VpcConfigFactory?.Build();
        result.ModelSource ??= ModelSourceFactory?.Build();
    }

} // End Of Class

